import { cacheLife, cacheTag } from 'next/cache'

export type Invoice = {
  id: string
  name: string
  amount: number
}

export type RevenuePoint = {
  month: string
  amount: number
}

export type DashboardStats = {
  totalRevenue: number
  totalInvoices: number
}

async function safeJson<T>(req: Promise<Response>, fallback: T): Promise<T> {
  try {
    const res = await req
    return (await res.json()) as T
  } catch {
    return fallback
  }
}

export async function getDashboardStats(): Promise<DashboardStats> {
  'use cache'
  cacheLife('hours')
  cacheTag('dashboard', 'stats')
  return safeJson<DashboardStats>(
    fetch('https://api.example.com/dashboard/stats'),
    { totalRevenue: 0, totalInvoices: 0 },
  )
}

export async function getRevenue(): Promise<RevenuePoint[]> {
  'use cache'
  cacheLife('hours')
  cacheTag('dashboard', 'revenue')
  return safeJson<RevenuePoint[]>(
    fetch('https://api.example.com/dashboard/revenue'),
    [],
  )
}

export async function getLatestInvoices(): Promise<Invoice[]> {
  const res = await fetch(
    'https://api.example.com/dashboard/invoices/latest',
    { cache: 'no-store' },
  )
  return res.json().catch(() => [] as Invoice[])
}

